    public const string Options = "Opções";
    public const string Technical = "Análise técnica";
    public const string Fundamentals = "Fundamentos e macro";
    public const string Risk = "Risco e desempenho";
    public const string Slang = "Gíria";
    public const string SmartMoney = "ICT / Smart Money";

    public static IReadOnlyList<TradingTerm> Terms { get; } =
    [
        new("Market order", "Ordem a mercado", Orders, "Compra ou vende logo ao melhor preço disponível. Garante a execução, não o preço.", "Buys or sells immediately at the best available price. Guarantees execution, not the price."),
        new("Limit order", "Ordem limitada", Orders, "Só executa ao preço que definiste ou melhor. Garante o preço, não a execução.", "Only executes at your chosen price or better. Guarantees the price, not the execution."),
        new("Stop order / Stop-loss", "Ordem stop / Stop-loss", Orders, "Ordem que se ativa quando o preço atinge um nível, normalmente para limitar uma perda. Passa a ordem a mercado ao ser tocada, por isso o preço final pode ser pior.", "An order triggered when price reaches a level, usually to cap a loss. It becomes a market order once hit, so the fill price can be worse."),
        new("Stop-limit order", "Ordem stop-limite", Orders, "Um stop que, ao ser ativado, cria uma ordem limitada em vez de a mercado. Controla o preço, mas pode não executar.", "A stop that places a limit order when triggered instead of a market order. Controls the price, but may not fill."),
