        new("Trailing stop", "Stop dinâmico (trailing stop)", Orders, "Stop que acompanha o preço a uma distância fixa quando ele vai a teu favor, e não recua.", "A stop that follows price at a fixed distance when it moves in your favour, and never moves back."),
        new("OCO (one cancels the other)", "OCO (uma cancela a outra)", Orders, "Duas ordens ligadas, normalmente stop e alvo: quando uma executa, a outra é cancelada.", "Two linked orders, usually stop and target: when one fills, the other is cancelled."),
