        new("Bid", "Preço de compra (bid)", Orders, "O preço mais alto que alguém está disposto a pagar agora. É o preço a que vendes a mercado.", "The highest price someone is willing to pay now. It is the price at which you sell at market."),
        new("Ask (offer)", "Preço de venda (ask)", Orders, "O preço mais baixo a que alguém vende agora. É o preço a que compras a mercado.", "The lowest price at which someone sells now. It is the price at which you buy at market."),
        new("Spread", "Spread (diferencial)", Orders, "Diferença entre ask e bid. É um custo implícito de cada operação.", "The difference between ask and bid. It is an implicit cost of every trade."),
        new("Liquidity", "Liquidez", Orders, "Facilidade de comprar ou vender sem mexer no preço. Muito volume e spread curto indicam boa liquidez.", "How easily you can buy or sell without moving the price. High volume and a tight spread mean good liquidity."),
        new("Volume", "Volume", Orders, "Quantidade de unidades negociadas num período. Confirma a força de um movimento.", "Number of units traded in a period. It confirms the strength of a move."),
        new("Gap", "Gap (salto de preço)", Orders, "Espaço sem negociação entre o fecho de uma sessão e a abertura seguinte, normalmente por notícias. Pode ultrapassar o stop sem o executar ao preço definido.", "A space with no trading between one session's close and the next open, usually due to news. It can jump over your stop and fill it at a worse price."),
        new("Pre-market / After-hours", "Pré-mercado / Pós-mercado", Orders, "Negociação antes da abertura e depois do fecho oficial, com menos liquidez e spreads maiores.", "Trading before the open and after the official close, with lower liquidity and wider spreads."),

        new("Long (buy)", "Posição longa (compra)", Positions, "Comprar a esperar que o preço suba. Ganhas se subir, perdes se descer.", "Buying in the expectation that price will rise. You profit if it goes up and lose if it goes down."),
        new("Short (sell short)", "Posição curta (venda a descoberto)", Positions, "Vender algo que não tens (emprestado ou via CFD) a esperar que desça, para recomprar mais barato. A perda teórica é ilimitada.", "Selling something you don't own (borrowed or via CFD) expecting it to fall, to buy it back cheaper. The theoretical loss is unlimited."),
        new("Buy to open / Sell to close", "Comprar para abrir / Vender para fechar", Positions, "Abrir uma posição longa e fechá-la. O inverso numa venda a descoberto é 'sell to open' e 'buy to cover'.", "Opening a long position and closing it. In a short sale the reverse is 'sell to open' and 'buy to cover'."),
        new("Cover (buy to cover)", "Cobrir (comprar para cobrir)", Positions, "Comprar de volta para fechar uma posição curta.", "Buying back to close a short position."),
        new("Entry / Exit", "Entrada / Saída", Positions, "O preço e o momento em que abres e em que fechas uma posição.", "The price and moment at which you open and close a position."),
        new("Position size", "Tamanho da posição", Positions, "Quanto compras ou vendes. Deve resultar do risco que aceitas e da distância ao stop.", "How much you buy or sell. It should follow from the risk you accept and the distance to the stop."),
        new("Lot", "Lote", Positions, "Unidade-padrão de negociação, sobretudo em forex (1 lote padrão = 100 000 unidades da moeda base).", "Standard trading unit, mostly in forex (1 standard lot = 100,000 units of the base currency)."),
        new("Pip", "Pip", Positions, "Menor variação habitual de um par de moedas, normalmente 0,0001 (0,01 nos pares com iene).", "The usual smallest move of a currency pair, normally 0.0001 (0.01 for yen pairs)."),
        new("Tick", "Tick", Positions, "A menor variação de preço permitida num instrumento.", "The smallest price move allowed for an instrument."),
        new("Hedge", "Cobertura (hedge)", Positions, "Posição aberta para reduzir o risco de outra, por exemplo comprar uma put para proteger ações.", "A position opened to reduce the risk of another, for example buying a put to protect shares."),
        new("Scalping", "Scalping", Positions, "Dezenas de operações muito curtas, de segundos a minutos, para ganhos pequenos. Os custos pesam muito.", "Dozens of very short trades, from seconds to minutes, for small gains. Costs weigh heavily."),
        new("Day trading", "Negociação intradiária (day trading)", Positions, "Abrir e fechar posições no mesmo dia, sem ficar com risco overnight.", "Opening and closing positions on the same day, with no overnight risk."),
