        new("Position trading", "Negociação de longo prazo", Positions, "Manter meses ou anos, guiado por tendências e fundamentos.", "Holding for months or years, driven by trends and fundamentals."),
        new("Bull market / Bullish", "Mercado de alta (touro) / Otimista", Positions, "Fase de preços a subir de forma sustentada; 'bullish' é ter a expectativa de subida.", "A phase of sustained rising prices; 'bullish' means expecting a rise."),
        new("Bear market / Bearish", "Mercado de baixa (urso) / Pessimista", Positions, "Fase de queda sustentada (tipicamente −20% ou mais); 'bearish' é esperar descida.", "A phase of sustained decline (typically −20% or more); 'bearish' means expecting a fall."),
        new("Sideways market (range)", "Mercado lateral", Positions, "Preço a oscilar entre um mínimo e um máximo sem tendência clara.", "Price oscillating between a low and a high with no clear trend."),
        new("Rally", "Subida forte (rally)", Positions, "Subida rápida e prolongada do preço.", "A fast, sustained rise in price."),
        new("Correction", "Correção", Positions, "Descida de 10% ou mais face ao máximo recente, sem ser uma tendência de baixa.", "A decline of 10% or more from a recent high that is not a bear trend."),
        new("Crash", "Colapso (crash)", Positions, "Queda muito rápida e forte, normalmente com pânico.", "A very fast, steep fall, usually with panic."),

        new("Margin", "Margem", Margin, "Dinheiro que a corretora te exige como garantia para manteres uma posição alavancada.", "Money your broker requires as collateral to hold a leveraged position."),
        new("Leverage", "Alavancagem", Margin, "Usar margem para abrir uma posição maior do que o capital. Com 5× uma variação de 1% vale 5% da margem, para ganhos e perdas.", "Using margin to open a position larger than your capital. At 5× a 1% move is worth 5% of the margin, for gains and losses."),
        new("Margin call", "Chamada de margem (margin call)", Margin, "Aviso da corretora de que o capital caiu abaixo do nível exigido: tens de depositar mais dinheiro ou reduzir posições, senão fecham-nas por ti.", "A broker warning that your equity fell below the required level: you must deposit more money or reduce positions, or they will close them for you."),
        new("Stop out (liquidation)", "Fecho forçado (stop out / liquidação)", Margin, "A corretora fecha posições automaticamente quando a margem é insuficiente, muitas vezes com perdas realizadas e sem aviso.", "The broker automatically closes positions when margin is insufficient, often locking in losses without warning."),
