        new("MACD", "MACD", Technical, "Indicador de momentum baseado na diferença entre duas médias exponenciais. Os cruzamentos sinalizam mudanças de força.", "A momentum indicator based on the difference between two exponential averages. Crossovers signal changes in strength."),
