        new("EPS (earnings per share)", "Lucro por ação (EPS)", Fundamentals, "Lucro da empresa dividido pelo número de ações.", "Company profit divided by the number of shares."),
        new("P/E ratio", "Rácio preço/lucro (PER)", Fundamentals, "Preço da ação a dividir pelo lucro por ação. Mostra quantos anos de lucro estás a pagar.", "Share price divided by earnings per share. It shows how many years of earnings you are paying for."),
        new("Guidance", "Previsões da gestão (guidance)", Fundamentals, "Expectativas que a empresa dá para resultados futuros. Muitas vezes mexe mais no preço do que os números passados.", "Expectations a company gives for future results. It often moves price more than past numbers."),
